function toast(message,tone=''){ const el=document.createElement('div');el.className=`toast ${tone}`;el.textContent=message;$('#toasts').append(el);while($('#toasts').children.length>3)$('#toasts').firstElementChild.remove();setTimeout(()=>el.remove(),4800);}
function setSelection(ids){selectionKey='';selection=[...new Set(ids)].filter(id=>{const e=sim.get(id);return e&&!e.embarked;});view.selection=new Set(selection);$('#selection-panel').scrollTop=0;$('#selection-panel').classList.remove('selection-expanded');audio.play('select');renderSelection();}
function selected(){return selection.map(id=>sim.get(id)).filter(Boolean);}
function workers(){return selected().filter(e=>e.owner===0&&e.type==='villager').map(e=>e.id);}
function updateCameraLabel(){const label=$('#camera-view-label');if(label)label.textContent=(CAMERA_PRESETS[settings.cameraPreset]||CAMERA_PRESETS.balanced).label;}
function closeModal(){if(view?.graphicsFatal&&modal==='graphics-recovery')return;if(modal==='pause'||modal==='settings-game'||modal==='help-game'||modal==='codex-game'||modal==='tree-game'||modal==='journal-game'||modal==='alliance')paused=false;modal=null;$('#modal-root').innerHTML='';const opener=modalOpener;modalOpener=null;if(opener?.isConnected&&opener.getClientRects().length)opener.focus({preventScroll:true});}
function showModal(content,kind='info',wide=false){chat.close(false);if(!modal)modalOpener=document.activeElement;edgeScroll.reset();modal=kind;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true"><button class="modal-close" data-action="close" aria-label="Close dialog">${uiIcon("x")}</button>${content}</section></div>`;const dialog=$('#modal-root .modal'),heading=dialog.querySelector('h2');if(heading){heading.id='dialog-heading';dialog.setAttribute('aria-labelledby',heading.id);}if(kind==='end')dialog.classList.add('result-dialog');if(kind==='settings'||kind==='settings-game')appendKeyboardSettings($('#modal-root'),settings.bindings);if(kind==='help'||kind==='help-game')$('#modal-root .help-grid').after(Object.assign(document.createElement('section'),{className:'current-controls',innerHTML:'<h3>Your active keyboard controls</h3>'+activeControlsMarkup(settings.bindings)}));$('#modal-root').querySelector('button')?.focus({preventScroll:true});}
function showSetup(mode){if(mode==='custom')return showCustomBattle();const m=MODES.find(m=>m.id===mode)||MISSIONS.find(m=>m.id===mode);showModal(`<div class="eyebrow">${m.chapter?`CHAPTER ${m.chapter} · THE FRONTIER CHRONICLES`:m.label}</div><h2>${m.name}</h2><p class="modal-intro">${m.desc}</p><div class="setup-grid"><div><label class="field-label" for="faction">YOUR CIVILIZATION</label><select id="faction">${Object.entries(FACTIONS).map(([id,f])=>`<option value="${id}" ${id===setupOptions.faction?'selected':''}>${f.name}</option>`).join('')}</select><div id="faction-description" class="faction-description"></div></div><div><label class="field-label" for="difficulty">DIFFICULTY</label><select id="difficulty">${Object.entries(DIFFICULTIES).map(([id,d])=>`<option value="${id}" ${id===setupOptions.difficulty?'selected':''}>${difficultyLabel(id,d.name)}</option>`).join('')}</select><div id="difficulty-description" class="faction-description"></div></div><div><label class="field-label" for="map">BATTLEFIELD</label><select id="map" ${m.map?'disabled':''}>${Object.entries(MAPS).map(([id,map])=>`<option value="${id}" ${id===(m.map||setupOptions.map)?'selected':''}>${map.name}</option>`).join('')}</select></div><div><label class="field-label" for="seed">WORLD SEED</label><input id="seed" type="number" min="1" max="999999999" value="${m.seed||setupOptions.seed}"></div></div><div class="mission-brief"><span>VICTORY CONDITION</span><p>${m.objective}</p><small>${m.time||'A campaign chapter'} · Mouse & touch supported</small></div><button class="primary full" data-start="${mode}">${mode==='tutorial'?'Start the tutorial':'Start battle'} ${uiIcon("chevron-right")}</button>`, 'setup');updateSetupDescriptions();}
function updateSetupDescriptions(){if($('#faction')){$('#faction-description').textContent=FACTIONS[$('#faction').value].desc;$('#difficulty-description').textContent=DIFFICULTIES[$('#difficulty').value].desc;}}
function showCustomBattle(preset=null){if(playing)paused=true;if(preset){if(modal==='custom-setup')customDraft=readBattleSetup($('#modal-root'));customDraft.slots=battlePreset(preset);const role=Number(customDraft.playerSlot);if(role>0&&!customDraft.slots[role-1]?.enabled){customDraft.playerSlot=1;customDraft.spectator=false;}}showModal(customBattleMarkup(customDraft),'custom-setup',true);$('#modal-root .modal').classList.add('custom-dialog');updateBattlePreview($('#modal-root'));}
function launchCustom(multiplayer){
  try{customDraft=readBattleSetup($('#modal-root'));localStorage.setItem('crowns-custom-setup',JSON.stringify(customDraft));
    if(multiplayer&&customDraft.spectator)return toast('Choose a player slot before hosting multiplayer. Spectator mode is for solo battles.','warning');
    if(!multiplayer)return startGame(normalizeBattle({...customDraft,multiplayer:false}));
    const options=customHostOptions(customDraft);if(net.socket)net.leave();showModal('<h2>Creating your war room...</h2><button class="secondary" data-action="lan-leave">Cancel</button>','lan');net.connect({type:'create',name:options.slots[0].name,faction:options.slots[0].faction,options});
  }catch(error){toast(error.message,'warning');}
}
function showJournal(){if(!sim.campaignState||sim.campaignState.legacy)return;if(playing)paused=true;showModal('<div class="eyebrow">THE FRONTIER CHRONICLES</div><h2>Campaign journal.</h2><div class="campaign-journal">'+sim.campaignState.history.map(entry=>'<article><span>'+esc(entry.speaker)+' · '+formatTime(entry.time)+'</span><p>'+esc(entry.text)+'</p></article>').join('')+'</div><p class="journal-optional">Optional goal: '+esc(CAMPAIGN_SCRIPTS[sim.options.mode].optional.text)+'</p>','journal-game',true);}
function showCampaign(){showModal(`<div class="eyebrow">THE FRONTIER CHRONICLES</div><h2>A kingdom in the making.</h2><p class="modal-intro">Six story chapters, or create your own battle with configurable allies, rivals, and victory rules.</p><button class="secondary full" data-action="custom-battle">Create your own custom battle</button><div class="chapter-list">${MISSIONS.map(m=>`<button class="chapter" data-mode="${m.id}"><span class="chapter-number">${m.chapter}</span><span><strong>${m.name}</strong><small>${m.desc}</small></span><span class="chapter-status">${progress[m.id]?.optional?uiIcon('trophy'):progress[m.id]?uiIcon('check'):uiIcon('chevron-right')}</span></button>`).join('')}</div>`, 'campaign',true);}
function startGame(options,save=null){if(!view)return;chat.close(false);if(!net.active)chat.reset();resetCompactHud(document);audio.clearCombat();edgeScroll.reset();audio.lastThunder=undefined;tacticalMode=null;unloadMode=false;productionOpen=false;productionKey='';$('#production-panel').classList.add('hidden');$('#production-toggle').setAttribute('aria-expanded','false');$('#hud').classList.remove('panels-hidden');$('[data-action=camera-panels]').setAttribute('aria-pressed','false');closeModal();setupOptions={...setupOptions,...options};sim=save?Simulation.restore(save):new Simulation(options);$('#hud').classList.toggle('ai-spectator',isAISpectator());view.attach(sim);sim.on(onEvent);playing=true;paused=false;speed=1;groups={};$('#toasts').innerHTML='';selection=[];view.selection=new Set();cancelBuild();attackMove=false;simulationPacer.reset();accumulator=0;lastAutosave=sim.time;$('#landing').classList.add('hidden');$('#hud').classList.remove('hidden');view.angle=Math.PI/4;view.setCameraPreset(settings.cameraPreset,true);updateCameraLabel();audio.unlock();renderHUD();renderSelection();updateRotate();toast(isAISpectator()?'The AI commanders are taking the field. Select a kingdom on the roster to follow.':'Your kingdom awaits. Select a villager or your town center.');if(sim.options.mode==='tutorial')toast('Start with the objectives in the upper-left corner.');if(sim.ended)showEnd(sim.ended);}
function onEvent(e){if(['notice','research','sound'].includes(e.type)&&e.owner!==undefined&&e.owner!==0)return;
  if(isAISpectator()&&['notice','research','sound','complete','trained','alarm','raid','wave','capture','donation'].includes(e.type))return;
  if(e.type==='notice')toast(e.message,e.tone);
  if(e.type==='kingdom-defeated')toast(`${e.name} has been eliminated.${e.owner===0&&!isAISpectator()?' You can watch your allies continue.':''}`);
  if(e.type==='remnants-revealed')toast(`${e.name}: the last buildings are marked on the radar.`);
  if(e.type==='ally-support'&&sim.allied(0,e.ally))toast(`${sim.players[e.owner]?.name||'Your ally'} is sending ${e.count} reinforcements to ${e.ally===0?'your base':sim.players[e.ally]?.name||'an allied base'}.`);
  if(e.type==='donation'&&(e.from===0||e.to===0)){toast(e.from===0?`Sent ${e.amount} ${e.resource} to ${sim.players[e.to].name}.`:`${sim.players[e.from].name} sent you ${e.amount} ${e.resource}.`);renderHUD();refreshAllianceModal(modal==='alliance'?$('#modal-root'):null,sim,allianceRecipient);}
  if(e.type==='complete'){toast(`${BUILDINGS[e.entity.type].name} completed.`);audio.play('complete');renderSelection();}
  if(e.type==='trained'&&e.entity.owner===0){audio.play('complete');if(e.entity.type==='villager'&&!e.entity.order)sim.assignWorker(e.entity);}
  if(e.type==='research'){toast(e.tech==='age'?`${AGES[e.age]} reached. New troops and buildings unlocked.`:`${TECHS[e.tech].name} completed.`);audio.play('complete');renderSelection();}
  if(e.type==='order'){audio.play('order');}
  if(e.type==='sound')audio.play(e.name);
  if(e.type==='alarm'){$('#alert-line').innerHTML='<span class="alert-pulse"></span> YOUR KINGDOM IS UNDER ATTACK';audio.play('alarm');setTimeout(()=>$('#alert-line').innerHTML='',7000);}
  if(e.type==='raid')toast('Scouts report an enemy army on the move.','warning');
  if(e.type==='wave'){toast(`Wave ${e.wave} · ${e.count} enemies approach. Supplies have arrived.`,'warning');audio.play('alarm');}
  if(e.type==='capture'){toast(e.owner===0?'An ancient shrine is under your control.':'The enemy has captured a shrine.',e.owner===0?'':'warning');audio.play('complete');}
  if(e.type==='attack'||e.type==='projectile-impact'||e.type==='death'||e.type==='heal'){view.effect(e);if(e.type==='attack'){if(e.pendingImpact)audio.combat(e.entity,e.target,['catapult','warship'].includes(e.entity.type)?'wood':'arrow');else audio.play('attack',e.entity,e.target);}if(e.type==='projectile-impact')audio.combat(e.target,e.entity,projectileImpactSound(e));}
  if(e.type==='campaign-stage'){toast(e.text);audio.play('complete');renderHUD();}
  if(e.type==='campaign-checkpoint'){saveGame(true);toast('Campaign checkpoint saved. Restore it from the commander menu.');}
  if(e.type==='end')showEnd(e);
}
function saveGame(automatic=false){const result=writeLocalSave(sim,{networkActive:net.active});if(!automatic){if(result==='network')toast('Network games reconnect through the room session. Local saving is for single-player matches.');else if(result==='saved')toast('Your kingdom has been saved on this device.');else toast('This browser could not store the save. Free storage or enable local storage.','warning');}return result==='saved';}
function showEnd(result){paused=true;buildType=null;view.hideGhost();if(!result.spectator&&result.won){progress[sim.options.mode]=sim.campaignState&&!sim.campaignState.legacy?{won:true,optional:sim.campaignState.optional,route:sim.campaignState.route,seconds:sim.time}:true;try{localStorage.setItem('crowns-progress',JSON.stringify(progress));}catch{}audio.play('victory');}if(result.spectator){const winner=result.winningTeam===null?'No team':'Team '+result.winningTeam+' wins';showModal('<div class="result-crest">AI</div><div class="eyebrow">AI BATTLE OBSERVED</div><h2>Battle complete.</h2><p class="modal-intro">'+esc(result.reason)+' '+winner+'.</p><div class="result-stats"><div><strong>'+formatTime(sim.time)+'</strong><span>TIME IN BATTLE</span></div><div><strong>'+sim.stats.kills+'</strong><span>ENEMIES DEFEATED</span></div><div><strong>'+Math.round(sim.stats.gathered)+'</strong><span>RESOURCES GATHERED</span></div><div><strong>'+sim.stats.built+'</strong><span>BUILDINGS RAISED</span></div></div>'+battleResultMarkup(sim)+'<div class="result-actions"><button class="primary" data-action="restart">Watch another battle</button><button class="secondary" data-action="menu">Return to menu</button></div>','end');return;}showModal('<div class="result-crest">'+uiIcon(result.won?'trophy':'shield')+'</div><div class="eyebrow">'+(result.won?'A LEGACY WRITTEN':'THE CROWN HAS FALLEN')+'</div><h2>'+(result.won?'Victory.':'Defeat.')+'</h2><p class="modal-intro">'+esc(result.reason)+'</p><div class="result-stats"><div><strong>'+formatTime(sim.time)+'</strong><span>TIME IN BATTLE</span></div><div><strong>'+sim.stats.kills+'</strong><span>ENEMIES DEFEATED</span></div><div><strong>'+Math.round(sim.stats.gathered)+'</strong><span>RESOURCES GATHERED</span></div><div><strong>'+sim.stats.built+'</strong><span>BUILDINGS RAISED</span></div></div>'+battleResultMarkup(sim)+(sim.campaignState?.finished?'<p class="campaign-medal">'+(sim.campaignState.optional?'Optional goal completed':'Chapter completed')+'</p>':'')+'<div class="result-actions">'+(sim.campaignCheckpoint&&!result.won?'<button class="primary" data-action="checkpoint">Restore campaign checkpoint</button>':'')+'<button class="primary" data-action="restart">Play again</button><button class="secondary" data-action="menu">Return to menu</button></div>','end');}
function showPause(){paused=true;const network=net.active||!!sim.options.multiplayer;showModal(`<div class="eyebrow">${network?"MULTIPLAYER":"PAUSE MENU"}</div><h2>${network?'Commander menu':'Game paused'}</h2>${network?'<p class="modal-intro">The network match continues while this menu is open.</p>':''}<p class="modal-intro">${AGES[sim.players[0].age]} · ${formatTime(sim.time)} · ${DIFFICULTIES[sim.options.difficulty].name}</p><div class="pause-actions"><button class="primary full" data-action="close">Return to battle ${uiIcon("chevron-right")}</button>${network?'':'<button class="secondary full" data-action="save">Save kingdom</button>'}${sim.campaignCheckpoint?'<button class="secondary full" data-action="checkpoint">Restore campaign checkpoint</button>':''}${sim.campaignState&&!sim.campaignState.legacy?'<button class="secondary full" data-action="journal">Campaign journal</button>':''}<button class="secondary full" data-action="settings">Settings</button><button class="secondary full" data-action="help">Controls & strategy</button><button class="secondary full" data-action="fullscreen">Enter fullscreen</button>${sim.options.mode==='custom'&&!sim.players[0].defeated&&!sim.options.spectator?'<button class="text-button" data-action="resign">Resign your kingdom</button>':''}<button class="text-button" data-action="menu">${network?'Leave battle & return to menu':'Save & return to menu'}</button></div>`,'pause');}
function showSettings(){
  if(playing)paused=true;const graphicsMode=graphicsSelection(settings);
  showModal(`<div class="eyebrow">MAKE IT YOURS</div><h2>Settings</h2>
    <label class="field-label" for="quality">GRAPHICS QUALITY</label><select id="quality" aria-describedby="graphics-quality-help">
      <option value="auto" ${graphicsMode==='auto'?'selected':''}>Automatic · adjust to your device</option>
      <option value="high" ${graphicsMode==='high'?'selected':''}>High · detailed models & sharp surfaces</option>
      <option value="medium" ${graphicsMode==='medium'?'selected':''}>Balanced · detailed bases, lighter armies</option>
      <option value="low" ${graphicsMode==='low'?'selected':''}>Performance · lighter models & soft contacts</option>
    </select><p id="graphics-quality-help" class="settings-note">Automatic may lower graphics to keep play smooth. High, Balanced, and Performance stay at your chosen quality. Tree shapes stay consistent in every preset.</p>
    <p id="renderer-status" class="settings-note">${esc(rendererStatus({requested:requestedRenderer,active:rendererBackend(view.renderer),secure:globalThis.isSecureContext!==false}))}</p>
    ${graphicsSupport()}
    <label class="field-label" for="frame-rate">FRAME RATE TARGET</label><select id="frame-rate">${Object.entries(FRAME_RATES).map(([id,name])=>`<option value="${id}" ${settings.frameRate===id?'selected':''}>${name}</option>`).join('')}</select>
    <label class="field-label" for="camera-preset">CAMERA VIEW</label><select id="camera-preset">${Object.entries(CAMERA_PRESETS).map(([id,p])=>`<option value="${id}" ${settings.cameraPreset===id?'selected':''}>${p.label}</option>`).join('')}</select>
    <label class="toggle"><input id="edge-scroll" type="checkbox" ${settings.edgeScroll?'checked':''}> Mouse edge scrolling</label>
    <label class="field-label" for="edge-scroll-speed">MOUSE SCROLL SPEED</label><input type="range" id="edge-scroll-speed" min=".5" max="2" step=".25" value="${settings.edgeScrollSpeed}">
    <label class="field-label" for="volume">VOLUME</label><input type="range" id="volume" min="0" max="1" step=".05" value="${settings.volume}">
    <label class="toggle"><input id="music" type="checkbox" ${settings.music?'checked':''}> Ambient music</label>
    <label class="field-label" for="weather-mode">WEATHER</label><select id="weather-mode"><option value="auto" ${settings.weather==='auto'?'selected':''}>Automatic weather</option>${Object.entries(WEATHER_NAMES).map(([id,name])=>`<option value="${id}" ${settings.weather===id?'selected':''}>${name}</option>`).join('')}</select>
    <label class="field-label" for="lighting-mode">BATTLEFIELD LIGHTING</label><select id="lighting-mode">${Object.entries(LIGHTING_MODES).map(([id,name])=>`<option value="${id}" ${(settings.lighting||'day')===id?'selected':''}>${name}</option>`).join('')}</select><p class="settings-note">Choose daylight, a readable moonlit battlefield, or a gradual 18-minute day and night cycle. Weather works with every lighting mode.</p>
    <label class="toggle"><input id="weather-sounds" type="checkbox" ${settings.weatherSounds?'checked':''}> Rain, wind, and thunder sounds</label>
    <label class="toggle"><input id="weather-lightning" type="checkbox" ${settings.lightning?'checked':''}> Lightning flashes <small>Reduced motion also disables flashes.</small></label>
    <label class="toggle"><input id="fog" type="checkbox" ${settings.fog?'checked':''}> Fog overlay <small>Enemy visibility rules remain active.</small></label>
    <label class="toggle"><input id="high-contrast" type="checkbox" ${settings.highContrast?'checked':''}> Higher contrast interface</label>
    <label class="toggle"><input id="reduced-motion" type="checkbox" ${settings.reducedMotion?'checked':''}> Reduce decorative motion</label>
    <p class="settings-note">Use landscape on phones. Drag to pan and tap to select or command. Pinch the battlefield or use the camera + / - buttons to change distance. The interface stays at its normal size. Saves are stored on this browser and device.</p>
    <button class="primary full" data-action="apply-settings">Apply settings ${uiIcon("check")}</button>`,playing?'settings-game':'settings');
}
function showCredits(){if(playing)paused=true;showModal(`<div class="eyebrow">CROWNS OF THE FRONTIER</div><h2>About & credits</h2><p class="modal-intro">An original 3D real-time strategy game for mouse and touch.</p><section class="interface-credits"><h3>Interface artwork</h3><p>Interface symbols are from <a href="https://lucide.dev" target="_blank" rel="noopener">Lucide</a>, used under the ISC license.</p><p>The siege ram is by Skoll and the trebuchet is by Delapouite, from <a href="https://game-icons.net" target="_blank" rel="noopener">Game-icons.net</a>, used under <a href="https://creativecommons.org/licenses/by/3.0/" target="_blank" rel="noopener">CC BY 3.0</a>. Icons are resized and recolored for this interface.</p><p><a href="/ICON_LICENSES.txt" target="_blank" rel="noopener">Full icon licenses and notices</a></p><h3>Typography</h3><p>DM Sans and Cormorant Garamond are bundled under the SIL Open Font License.</p></section>`,playing?'credits-game':'credits');}
function showHelp(){
  if(playing)paused=true;
  const phone=`<div><h3>Phone & tablet</h3><p>Play in landscape. Tap your units to select. With a unit selected, tap open ground to move, an enemy to attack, or a resource to gather.</p><p>Select a town center, castle or watchtower and tap <b>Shelter</b> to call nearby villagers inside. They add defensive arrows while gathering is paused. Tap <b>Return to work</b> to release them. Selected villagers also have a <b>Shelter</b> button.</p><p>Tap <b>Deselect</b> to clear your selection; your troops keep their orders. To inspect a different building, tap Deselect, then tap that building.</p><p>Drag the battlefield to look around, even with units selected. Pinch to change camera distance, or use the camera + / - buttons. This zooms the battlefield while the interface stays the same size. Use the rotation buttons under camera options to turn the view. Double-tap a troop to select nearby troops of the same type. <b>Army</b> selects your soldiers; <b>Idle</b> selects idle workers.</p><p>Tap <b>Build</b>, choose a building, then tap open land. For <b>walls</b>, tap a start and an end, or drag a line. Review the preview and stone cost, then tap <b>Build wall</b>. The camera stays still while drawing. Tap <b>Move map</b> to look around, then <b>Place wall</b> to continue. Pinch or use the camera + / - buttons to change distance without placing walls. <b>Reset</b> clears only the preview. <b>Cancel</b> or <b>Done</b> leaves the wall tool; already ordered walls keep building. Builders continue through your unfinished walls, including separate lines and individual sections. <b>Stop</b> or a new command interrupts their work. For other buildings, tap <b>Done building</b> to leave placement.</p><p>Placed something by mistake? Tap <b>Deselect</b>, select the building, then open its <b>Options</b>. <b>Cancel construction</b> refunds 70% for unfinished buildings; <b>Demolish</b> refunds 20% for completed buildings. Removing a wall leaves a real gap.</p><p>Tap or drag the square minimap to move the camera. Its outlined box and center dot locate your view. Tap <b>More</b> for Attack, Stop, Town and Map. Tap the selection's <b>Options</b> for research and advanced orders. Training appears on completed buildings. <b>P</b> in the top bar opens production; +5 queues a batch.</p><p>In multiplayer, tap <b>Chat</b> to message everyone or just your human allies. Close chat to free the battlefield. Chat messages stay only in the room while the server is running.</p><p>Tap pause, then <b>Controls & strategy</b>, to open this guide again.</p></div>`;
  const desktop=`<div><h3>Mouse & keyboard</h3><p>Move the mouse to an edge of the game window to scroll the camera. Corners scroll diagonally; the cursor arrow shows the direction. Use fullscreen to scroll at the screen edges. Adjust Mouse edge scrolling and its speed in Settings.</p><p>Click to select. Drag a box to select a group. Shift-click adds units. Double-click selects nearby troops of the same type.</p><p><b>Right-click</b> to move, attack, gather, build, repair, heal, or set a building's rally point. <b>Shift + right-click</b> queues orders.</p><p><b>WASD / arrows:</b> pan · <b>Q/E:</b> rotate · <b>V:</b> camera angle / <b>Wheel:</b> zoom · <b>Middle drag:</b> pan · <b>H:</b> town · <b>M:</b> army · <b>B:</b> build · <b>F:</b> attack move · <b>X:</b> stop · <b>.:</b> idle worker · <b>Esc:</b> pause/cancel</p><p><b>Walls:</b> choose Build → Wall, then click a start and an end or drag a line. Review the preview, then choose <b>Build wall</b>. Drawing locks mouse edge scrolling. Use <b>Move map</b>, middle drag, the minimap or camera keys to look around. <b>Reset</b> clears the preview; <b>Cancel</b>, right-click or Esc leaves the tool. Already ordered walls keep building.</p><p><b>Ctrl + 1–9:</b> store group · <b>1–9:</b> recall group · <b>Space:</b> focus selection</p></div>`;
  showModal(`<div class="eyebrow">THE COMMANDER'S HANDBOOK</div><h2>Controls & strategy</h2><div class="help-grid">${touchDevice?phone+desktop:desktop+phone}</div><div class="strategy-tip"><b>A good first five minutes</b><p>Keep training villagers. Build houses before reaching the population cap. Place gathering camps near resources. Mix spearmen with archers, advance your age, and bring siege weapons against fortifications. Add healers to preserve expensive troops.</p></div><button class="secondary" data-action="codex">Open the complete field guide</button><button class="text-button" data-action="credits">About & icon credits</button>`,playing?'help-game':'help',true);
}
let treeFaction=null;
function showTechnologyTree(faction=null){const top=modal==='tree'||modal==='tree-game'?$('#modal-root .modal').scrollTop:0;treeFaction=faction||(playing?sim.players[0].faction:setupOptions.faction);if(playing)paused=true;showModal(technologyTreeMarkup(playing?sim:null,treeFaction),playing?'tree-game':'tree',true);$('#modal-root .modal').classList.add('technology-modal');$('#modal-root .modal').scrollTop=top;}
function showCodex(tab='units'){if(playing)paused=true;const lists={units:UNITS,buildings:BUILDINGS,technologies:TECHS};showModal(`<div class="eyebrow">KNOWLEDGE IS POWER</div><h2>Field guide</h2><button class="secondary" data-action="tech-tree">Explore the technology tree</button><nav class="codex-tabs">${Object.keys(lists).map(t=>`<button class="${t===tab?'active':''}" data-codex="${t}">${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</nav><div class="codex-list">${Object.entries(lists[tab]).map(([id,d])=>`<article class="codex-item"><span class="codex-icon">${ICONS[id]||uiIcon('circle-help')}</span><div><h3>${d.name} <small>${AGES[d.age]}</small></h3><p>${d.desc}</p><span class="cost">${costText(d.cost)} ${d.hp?` · ${d.hp} base HP`:''} ${d.time?` · ${d.time}s`:''}</span></div></article>`).join('')}</div><div class="strategy-tip"><b>Unit counters</b><p>Spearmen → cavalry · cavalry → archers · archers → spearmen · armored infantry → light troops · siege → buildings. Troops gain strength with each age. Research stacks with civilization bonuses.</p></div>`,playing?'codex-game':'codex',true);}
function toggleBuild(){if(buildType){cancelBuild();return;}const ws=workers();if(!ws.length){const free=sim.owned(0,'unit','villager').filter(e=>!e.order&&!e.embarked);setSelection((free.length?free:sim.owned(0,'unit','villager').filter(e=>!e.embarked)).slice(0,2).map(e=>e.id));}if(!workers().length)return toast('Train a villager before constructing buildings.','warning');
  const age=sim.players[0].age;$('#build-panel').classList.remove('hidden');$('#build-panel').innerHTML=`<div class="floating-heading"><span>RAISE YOUR KINGDOM</span><button data-action="cancel-build" aria-label="Close construction">${uiIcon("x")}</button></div><div class="build-grid">${Object.entries(BUILDINGS).map(([id,d])=>`<button class="build-option ${age<d.age?'locked':''}" data-build="${id}" ${age<d.age?'disabled':''} title="${esc(d.desc)}"><span class="build-icon">${ICONS[id]}</span><strong>${d.name}</strong><small>${age<d.age?AGES[d.age]:costText(sim.cost(d.cost,0,'building'))}</small></button>`).join('')}</div><p class="build-footnote">Choose open land for buildings. For walls, tap a start and end or drag a line, then choose Build wall. Shift repeats other buildings.</p>`;
}
function cancelBuild(){buildType=null;wallDraft.clear();wallPlaced=false;wallPlan=null;wallPlanKey=wallControlsKey='';edgeScroll.reset();$('#hud').classList.remove('wall-placing');$('#build-panel').classList.add('hidden');$('#placement-controls').classList.add('hidden');$('#placement-controls').classList.remove('wall-controls');view?.wallPreview?.hide();view?.hideGhost();$('#world').classList.remove('placing');$('#order-hint').textContent=isAISpectator()?'Select a kingdom to watch the battle.':'Select units to issue orders.';}
function updateWallPlacement(force=false){
  if(buildType!=='wall'||!view||!sim)return;const now=performance.now();if(!force&&now-wallPlanAt<50)return;
  const ids=workers(),key=wallDraft.version+':'+sim.revision+':'+sim.players[0].age+':'+JSON.stringify(sim.players[0].resources)+':'+ids.join(',');
  if(!force&&key===wallPlanKey&&now-wallPlanAt<150)return;wallPlanAt=now;wallPlanKey=key;wallPlan=wallPlacementPlan(sim,wallDraft,ids);
  if(wallDraft.start){view.wallPreview??=new WallPreview(view);view.wallPreview.show(wallPlan);}else view.wallPreview?.hide();
  // Keep the actual buttons in place while a finger or keyboard focus rests
  // on them. Resource and preview refreshes must never replace a tap target.
  const controlKey=JSON.stringify([wallPlan.message,wallPlan.count,wallPlan.cost,wallPlan.canBuild,!!wallDraft.start,wallDraft.panning,wallPlaced]);if(controlKey===wallControlsKey)return;
  const panel=$('#placement-controls');if(!wallControlsKey)panel.innerHTML='<div class="wall-placement-status"><span role="status"></span><strong></strong></div><div class="wall-placement-actions"><button class="primary" data-action="wall-build">Build wall</button><button data-action="wall-reset">Reset</button><button data-action="wall-pan" aria-pressed="false">Move map</button><button data-action="cancel-build">Cancel</button></div>';wallControlsKey=controlKey;
  panel.querySelector('[role=status]').textContent=wallPlan.message;const summary=panel.querySelector('.wall-placement-status strong');summary.hidden=!wallPlan.count;summary.textContent=wallPlan.count?`${wallPlan.count} ${wallPlan.count===1?'wall':'walls'} · ${costText(wallPlan.cost)}`:'';
  panel.querySelector('[data-action=wall-build]').disabled=!wallPlan.canBuild;panel.querySelector('[data-action=wall-reset]').disabled=!wallDraft.start;const pan=panel.querySelector('[data-action=wall-pan]');pan.setAttribute('aria-pressed',String(wallDraft.panning));pan.textContent=wallDraft.panning?'Place wall':'Move map';panel.querySelector('[data-action=cancel-build]').textContent=wallPlaced?'Done':'Cancel';
}
function confirmWallPlacement(){
  if(buildType!=='wall')return;updateWallPlacement(true);if(!wallPlan.canBuild)return;const plan=wallPlan,built=sim.buildWallLine(plan.from,plan.to,workers());
  if(built===true||Array.isArray(built)&&built.length){wallPlaced=true;wallDraft.clear();wallPlan=null;wallPlanKey='';view.wallPreview?.hide();updateWallPlacement(true);toast(built===true?'Wall construction requested.':`${built.length} connected wall ${built.length===1?'section':'sections'} ordered. Tap a new start or choose Done.`);renderHUD();}
}
function attributes(e){const d=UNITS[e.type],p=sim.players[e.owner],attack=Math.round(d.damage*(1+p.age*.12)*(1+(d.role==='ranged'?p.tech.ranged:p.tech.attack)*.2)*(d.naval?1+(p.tech.seamanship||0)*.2:1)*(d.role==='cavalry'?FACTIONS[p.faction].cavalry:1));return `<div class="unit-attributes"><span>ATTACK<b>${attack}</b></span><span>ARMOR<b>${sim.unitArmor(e)}</b></span><span>RANGE<b>${d.range+(d.role==='ranged'?p.tech.ranged:0)}m</b></span><span>VISION<b>${d.vision}m</b></span></div>`;}
function applyAccessibility(){document.documentElement.classList.toggle('high-contrast',!!settings.highContrast);document.documentElement.classList.toggle('reduced-motion',!!settings.reducedMotion);}
function refreshShortcutLabels(){for(const button of document.querySelectorAll('[data-action]')){const key=settings.bindings[button.dataset.action];if(key){button.title=button.title.replace(/ \([^)]*\)$/,'')+' ('+keyLabel(key)+')';}}}
