  return `<div class="group-production">${choices.map(({type,data,sites})=>`<div class="production-choice"><button data-train="${type}" data-building="group" ${age<data.age?'disabled':''} title="${esc(data.desc)}"><span>${ICONS[type]}</span><strong>${data.name}</strong><small>${age<data.age?AGES[data.age]:`${costText(data.cost)} · ${sites.length} ${sites.length===1?'building':'buildings'}`}</small></button><button data-train="${type}" data-building="group" data-batch="5" ${age<data.age?'disabled':''} aria-label="Train five ${esc(data.name)}" title="Queue up to five">+5</button></div>`).join('')}</div>`;
