    if(playing&&!paused&&!modal&&!document.hidden)view.adapt(elapsed);else{view.renderPressure=null;view.performanceClock=0;}const renderInterval=document.hidden?1000:modal||!playing?100:1000/targetFrameRate(settings);if(framePacer.due(now,renderInterval)){if(view.render(Math.min(.2,(now-lastRender)/1000),!playing)!==false)lastRender=now;}audio.tick(dt);audio.weather(view.weatherState,playing&&!paused&&!sim.ended);const weatherLabel=$('#weather-label');if(weatherLabel){weatherLabel.textContent=view.weatherState?.type==='clear'?'Clear':WEATHER_NAMES[view.weatherState?.type]?.split(' ')[0]||'Clear';weatherLabel.parentElement.title=`Weather: ${WEATHER_NAMES[view.weatherState?.type]||'Clear'}. Mode: ${settings.weather}. Click to change.`;}
